mkdir -p /tmp/roofprobe && cat > /tmp/roofprobe/probe.mjs <<'EOF'
// Lists every write the Roofs part makes into a cell an earlier part already filled (runParts refuses these; its report keeps only 8).
const KIT = process.argv[2];
const { Grid } = await import("/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs");
const { SITE_SIZE, GROUND_Y } = await import(`${KIT}/vocab/base.mjs`);
const shellA = await import(`${KIT}/parts/shell_a.mjs`);
const stairs = await import(`${KIT}/parts/stairs.mjs`);
const shellB = await import(`${KIT}/parts/shell_b.mjs`);
const roofs = await import(`${KIT}/parts/roofs.mjs`);
const g = new Grid(SITE_SIZE);
g.fill([0, GROUND_Y, 0], [SITE_SIZE[0] - 1, GROUND_Y, SITE_SIZE[2] - 1], "grass_block");
for (const p of [shellA, stairs, shellB]) p.build(g);
const isAir = (c) => !c || c.block === "minecraft:air" || c.block === "air";
const hits = [];
const seen = new Set();
const rec = (x, y, z, block) => {
  const c = g.get(x, y, z);
  if (!isAir(c)) { const k = `${x},${y},${z}`; if (!seen.has(k)) { seen.add(k); hits.push([x, y, z, block, c.block.replace("minecraft:", "")]); } return false; }
  return true;
};
const view = new Proxy(g, {
  get(t, p) {
    if (p === "set") return (x, y, z, b, s, n) => { if (rec(x, y, z, b)) t.set(x, y, z, b, s, n); return view; };
    if (p === "fill") return (a, b, blk, s) => { for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++) for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++) for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) if (rec(x, y, z, blk)) t.set(x, y, z, blk, s); return view; };
    const v = Reflect.get(t, p);
    return typeof v === "function" ? v.bind(t) : v;
  },
});
roofs.build(view);
console.log(JSON.stringify(hits));
console.log("total", hits.length);
EOF
cd /tmp/roofprobe && node probe.mjs /Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/millkit3/crew/fix-4 2>&1 | tail -5

