    commit(g, { grow = true, protect, keep = [] }) {
      const all = [...m.values()];
      if (!all.length) return { cells: 0, refused: 0, shift: [0, 0, 0] };
      const lo = [0, 1, 2].map((i) => Math.min(0, ...all.map((e) => e.pos[i]))), hi = [0, 1, 2].map((i) => Math.max(g.size[i] - 1, ...all.map((e) => e.pos[i])));
      const shift = lo.map((v) => (v < 0 ? -v : 0));
      if (shift.some(Boolean) || hi.some((v, i) => v >= g.size[i])) {
        if (!grow) throw new Error(`roof form: does not fit the grid (needs ${lo} .. ${hi}); pass grow: true`);
        g.resize(hi.map((v, i) => v + shift[i] + 1), shift);
      }
      const inKeep = (p) => keep.some((b) => p.every((v, i) => v >= Math.min(b.from[i], b.to[i]) && v <= Math.max(b.from[i], b.to[i])));
